103	        String detailMessage = e.getReason() != null ? e.getReason() : ERROR_INVALID_REQUEST;
104	        logger.warn("Request failed at {} {}: {}", request.getMethod(), request.getRequestURI(), detailMessage);
105	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), detailMessage);
